<?php

namespace Daif\ChromePdfBundle\Messenger;

use Daif\ChromePdfBundle\Builder\BuilderInterface;

/**
 * Carries the state of a builder so the document can be generated by a Messenger worker.
 * Processors set on the builder are not carried over.
 */
final class GenerateDocumentMessage
{
    /**
     * @param class-string<BuilderInterface> $builderClass
     * @param array<string, mixed>           $bodyBag
     */
    public function __construct(
        public readonly string $builderClass,
        public readonly array $bodyBag,
        public readonly string|null $fileName,
        public readonly string $disposition,
        public readonly string $correlationId = '',
    ) {
    }
}
